namespace ExifGlass.Core.ExifTool;

/// <summary>
/// Two tiny images the daemon reads once after -ver, so the JPEG, EXIF and PNG modules are loaded before the first real file (S5).
/// </summary>
internal static class PrimingFiles
{
    #region Fields and constants

    // the 16 x 16 JPEG the AI fixtures are built on, and a 1 x 1 grey PNG
    private const string JPEG = "";
    private const string PNG = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAAAAAA6fptVAAAACklEQVR4nGNgAAAAAgABSK+kcQAAAABJRU5ErkJggg==";

    #endregion // Fields and constants


    #region Public methods

    /// <summary>
    /// Writes the files once into a temp folder and returns their paths; none when the folder can't be written.
    /// </summary>
    public static IReadOnlyList<string> Ensure()
    {
        try
        {
            var dir = Path.Combine(Path.GetTempPath(), "ExifGlass");
            Directory.CreateDirectory(dir);

            var jpeg = Path.Combine(dir, "prime.jpg");
            var png = Path.Combine(dir, "prime.png");
            if (!File.Exists(jpeg)) File.WriteAllBytes(jpeg, Convert.FromBase64String(JPEG));
            if (!File.Exists(png)) File.WriteAllBytes(png, Convert.FromBase64String(PNG));

            return [jpeg, png];
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return [];
        }
    }

    #endregion // Public methods
}
